#!/usr/bin/env python3
import sys
import json
import time
import urllib.request
import urllib.error

API_URL = "http://127.0.0.1:4000/v1/chat/completions"
PROMPT = "Reply with exactly one word: OK"
TIMEOUT_SECONDS = 30
MAX_TOKENS = 20


def usage():
    print(f"Usage: {sys.argv[0]} <models.json>", file=sys.stderr)
    sys.exit(1)


def load_models(path):
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)

    models = []

    def add_model(name):
        if isinstance(name, str):
            name = name.strip()
            if name and name not in models:
                models.append(name)

    # Supported shapes:
    # 1) ["model-a", "model-b"]
    # 2) {"models": ["model-a", "model-b"]}
    # 3) {"model_list": [{"model_name": "model-a"}, ...]}
    # 4) [{"model": "model-a"}, {"model_name": "model-b"}]
    if isinstance(data, list):
        for item in data:
            if isinstance(item, str):
                add_model(item)
            elif isinstance(item, dict):
                for key in ("model_name", "model", "name", "id"):
                    if key in item:
                        add_model(item[key])
                        break

    elif isinstance(data, dict):
        if "models" in data and isinstance(data["models"], list):
            for item in data["models"]:
                if isinstance(item, str):
                    add_model(item)
                elif isinstance(item, dict):
                    for key in ("model_name", "model", "name", "id"):
                        if key in item:
                            add_model(item[key])
                            break

        if "model_list" in data and isinstance(data["model_list"], list):
            for item in data["model_list"]:
                if isinstance(item, str):
                    add_model(item)
                elif isinstance(item, dict):
                    for key in ("model_name", "model", "name", "id"):
                        if key in item:
                            add_model(item[key])
                            break

    if not models:
        raise ValueError(
            "Could not find any models in JSON file. "
            "Expected a list of model names, a 'models' list, or a 'model_list'."
        )

    return models


def extract_error_message(raw_text):
    raw_text = (raw_text or "").strip()
    if not raw_text:
        return "Unknown error"

    try:
        data = json.loads(raw_text)
        if isinstance(data, dict):
            err = data.get("error")
            if isinstance(err, dict):
                for key in ("message", "detail", "type"):
                    if key in err:
                        return str(err[key])
            elif isinstance(err, str):
                return err

            for key in ("message", "detail"):
                if key in data:
                    return str(data[key])
    except Exception:
        pass

    return raw_text


def extract_response_text(raw_text):
    try:
        data = json.loads(raw_text)
        choices = data.get("choices", [])
        if not choices:
            return ""

        first = choices[0]
        message = first.get("message", {})
        content = message.get("content")

        if isinstance(content, str):
            return content

        if isinstance(content, list):
            parts = []
            for item in content:
                if isinstance(item, dict):
                    if "text" in item:
                        parts.append(str(item["text"]))
                    elif "content" in item:
                        parts.append(str(item["content"]))
                else:
                    parts.append(str(item))
            return "".join(parts)

        if "text" in first:
            return str(first["text"])

    except Exception:
        pass

    return ""


def preview(text, limit=50):
    text = (text or "").replace("\r", " ").replace("\n", " ").strip()
    return text[:limit]


def is_temperature_unsupported(error_message):
    msg = (error_message or "").lower()
    return "temperature" in msg


def post_chat_completion(model_name, include_temperature):
    payload = {
        "model": model_name,
        "messages": [
            {"role": "user", "content": PROMPT}
        ],
        "max_tokens": MAX_TOKENS,
    }
    if include_temperature:
        payload["temperature"] = 0

    body = json.dumps(payload).encode("utf-8")
    request = urllib.request.Request(
        API_URL,
        data=body,
        headers={"Content-Type": "application/json"},
        method="POST",
    )

    try:
        with urllib.request.urlopen(request, timeout=TIMEOUT_SECONDS) as response:
            raw = response.read().decode("utf-8", errors="replace")
            return True, extract_response_text(raw), ""
    except urllib.error.HTTPError as e:
        raw = e.read().decode("utf-8", errors="replace")
        return False, "", f"HTTP {e.code}: {extract_error_message(raw)}"
    except urllib.error.URLError as e:
        return False, "", f"URL error: {e.reason}"
    except Exception as e:
        return False, "", str(e)


def test_model(model_name):
    start = time.time()

    ok, response_text, error_text = post_chat_completion(model_name, include_temperature=True)

    if not ok and is_temperature_unsupported(error_text):
        ok, response_text, error_text = post_chat_completion(model_name, include_temperature=False)

    latency = time.time() - start

    if ok:
        passed = response_text.strip() == "OK"
        return {
            "model": model_name,
            "status": "PASS" if passed else "FAIL",
            "latency": latency,
            "response": preview(response_text),
        }

    return {
        "model": model_name,
        "status": "FAIL",
        "latency": latency,
        "response": preview(error_text),
    }


def print_table(results):
    headers = ("Model", "Status", "Latency", "Response")

    latency_strings = [f"{r['latency']:.2f}s" for r in results]

    model_width = max(len(headers[0]), max((len(r["model"]) for r in results), default=0))
    status_width = max(len(headers[1]), max((len(r["status"]) for r in results), default=0))
    latency_width = max(len(headers[2]), max((len(s) for s in latency_strings), default=0))
    response_width = max(len(headers[3]), max((len(r["response"]) for r in results), default=0))

    fmt = f"{{:<{model_width}}}  {{:<{status_width}}}  {{:>{latency_width}}}  {{:<{response_width}}}"

    print(fmt.format(*headers))
    print(fmt.format("-" * model_width, "-" * status_width, "-" * latency_width, "-" * response_width))

    for r in results:
        print(fmt.format(
            r["model"],
            r["status"],
            f"{r['latency']:.2f}s",
            r["response"],
        ))


def main():
    if len(sys.argv) != 2:
        usage()

    config_path = sys.argv[1]

    try:
        models = load_models(config_path)
    except Exception as e:
        print(f"Error loading models: {e}", file=sys.stderr)
        sys.exit(1)

    results = []
    for model in models:
        results.append(test_model(model))

    print_table(results)

    passed = sum(1 for r in results if r["status"] == "PASS")
    failed = len(results) - passed
    print()
    print(f"Total: {len(results)} models | ✅ {passed} working | ❌ {failed} failed")


if __name__ == "__main__":
    main()
